function LadderStruggleRankRewardDialog:OnInitialize()
    xTry(function()
        self.rank = self.controller.Argument.parameters.rank or 0
        self.rankPercentage = self.controller.Argument.parameters.rankPercentage
        local params = self.controller.Argument.parameters
        if isNotNull(params) and isNotNull(params.systemName) then
