function LadderStruggleRankRewardDialog:LoopModeFreshRewardCellList(maxNum)
    if not self.LoopListView.IsListViewInit then
        self.LoopListView:InitListView(maxNum, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopListView, maxNum)
    end
end

function LadderStruggleRankRewardDialog:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end

    local cell = loopListView:NewListViewItem("Cell")
    local LB_cell = GetLuaBehaviour(cell.gameObject, RewardCellLuaPath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        LB_cell:Init()
    end
    local LT_cell = LB_cell.Env
    LT_cell:SetPanelInfo(self.rewardData[index+1])

    return cell
end

function LadderStruggleRankRewardDialog:GetRewardData()
    self.rewardData = {}        -- 全部奖励数组
    local NoList = {}           -- 名次奖励数组
    local percentageList = {}   -- 百分比奖励数组
    local allData = CfUtils.GetCf(self.component.settingIdRankRewardVo, RewardVo, true)
    for i, v in ipairs(allData) do
        if v.type == 1 then
            table.insert(NoList, v)
        elseif v.type == 2 then
            table.insert(percentageList, v)
        end
        table.insert(self.rewardData, v)
        -- print("[异步PVP] 排名奖励", table.dump(allData, nil, 3))
    end

    -- 计算我自己的奖励
    local myRewardData
    for i, v in ipairs(NoList) do
        if v.upperLimit <= self.rank and self.rank <= v.lowerLimit then
            myRewardData = v
        end
    end
    if isNull(myRewardData) then
        for i, v in ipairs(percentageList) do
            if v.upperLimit <= self.rankPercentage and self.rankPercentage <= v.lowerLimit then
                myRewardData = v
            end
        end
    end
    if self.rank == 0 then
        if isNull(myRewardData) then
            myRewardData = {}
        end
        myRewardData.noRank = 1     -- 表示我没打过排位
    end
    self.myRewardData = myRewardData
end

return LadderStruggleRankRewardDialog


